// This function extracts only the numeric digits from a raw phone number.
// It removes spaces, parentheses, plus signs, hyphens, and any other non-digit character.

module.exports = async ({ params }) => {
  // Raw phone value from input
  let phone = params.phone;

  // Strip all non-digit characters (e.g., +, -, spaces, parentheses)
  let phoneDigits = phone.replace(/\D/g, "");

  // If it's a 10-digit NANP number, prepend "1"
  if (phoneDigits.length === 10) {
    phoneDigits = "1" + phoneDigits;
  }

  // Pretty formatting function for NANP-style numbers
  const formatPretty = (d) => {
    // 11-digit NANP: 1 + 10 digits
    if (d.length === 11 && d.startsWith("1")) {
      const area = d.slice(1, 4);
      const prefix = d.slice(4, 7);
      const line = d.slice(7, 11);
      return `+1 (${area}) ${prefix}-${line}`;
    }

    // 10-digit fallback (in case the user does not want the prepend)
    if (d.length === 10) {
      const area = d.slice(0, 3);
      const prefix = d.slice(3, 6);
      const line = d.slice(6, 10);
      return `(${area}) ${prefix}-${line}`;
    }

    // If non-NANP or unexpected length, return digits only
    return d;
  };

  const phonePretty = formatPretty(phoneDigits);

  return { "phoneDigits": phoneDigits, "formattedPhone": phonePretty };
};
